import unittest
from candidate import incr_list

class TestIncrList(unittest.TestCase):
    def test_incr_list_positive_numbers(self):
        self.assertEqual(incr_list([1, 2, 3]), [2, 3, 4])

    def test_incr_list_mixed_numbers(self):
        self.assertEqual(incr_list([5, 3, 5, 2, 3, 3, 9, 0, 123]), [6, 4, 6, 3, 4, 4, 10, 1, 124])

    def test_incr_list_zero(self):
        self.assertEqual(incr_list([0, 0, 0]), [1, 1, 1])

    def test_incr_list_negative_numbers(self):
        self.assertEqual(incr_list([-1, -2, -3]), [0, -1, -2])

    def test_incr_list_empty_list(self):
        self.assertEqual(incr_list([]), [])

    def test_incr_list_none_input(self):
        with self.assertRaises(TypeError):
            incr_list(None)

    def test_incr_list_non_list_input(self):
        with self.assertRaises(TypeError):
            incr_list("123")

    def test_incr_list_non_numeric_elements(self):
        with self.assertRaises(TypeError):
            incr_list([1, 2, "3"])

    def test_incr_list_float_elements(self):
        self.assertEqual(incr_list([1.5, 2.5, 3.5]), [2.5, 3.5, 4.5])

if __name__ == '__main__':
    unittest.main()
